#!/usr/bin/env python3
"""Toy 5663b — addendum to 5663 (same prereg 06205eb4; Cal §845 line 1: the sublattice Λ' generated by the
achievable Kempe shifts of the periods, tested in the same run): on T(6,6), every Kempe move on every rep;
record ΔP_x, ΔP_y, the set of shift vectors, the lattice they generate, and the class × datum contingency table."""
import importlib.util, os, json, sys, time
from collections import Counter, defaultdict
HERE = os.path.dirname(os.path.abspath(__file__))
spec = importlib.util.spec_from_file_location("t5663", os.path.join(HERE, "toy_5663_SEP4_R118_E5_kempe_invariance_of_the_height_datum_on_T3L3M_preregistered_06205eb4_T66_classes_fisk_degree_periods.py"))
src = open(spec.origin).read().split("# ================================================================== SPHERE CONTROLS")[0]
ns = {}; exec(compile(src, spec.origin, "exec"), ns)
torus, periods, kempe_moves, canon = ns["torus"], ns["periods"], ns["kempe_moves"], ns["canon"]
t0 = time.time()
T = torus(6, 6)
d = json.load(open(os.path.join(HERE, ".e5_5663_rows_T6x6.json")))
reps = [bytes.fromhex(h) for h in d["reps"]]; rows = d["rows"]
shifts = Counter(); shift_by_pair = Counter(); noncontractible = 0
for i, c in enumerate(reps):
    f = list(c); px, py = tuple(rows[i]["Px"]), tuple(rows[i]["Py"])
    for a in range(4):
        for b in range(a + 1, 4):
            for g, comp in ((g, comp) for g, comp in kempe_moves(T, f)):
                pass
            break
        break
    # explicit loop with pair info
    nv = T.nv
    for a in range(4):
        for b in range(a + 1, 4):
            seen = [False] * nv
            for v in range(nv):
                if seen[v] or f[v] not in (a, b): continue
                comp = []; stack = [v]; seen[v] = True
                while stack:
                    u = stack.pop(); comp.append(u)
                    for w in T.adj[u]:
                        if not seen[w] and f[w] in (a, b): seen[w] = True; stack.append(w)
                g = list(f)
                for u in comp: g[u] = a + b - g[u]
                Px2, Py2 = periods(T, g)
                dx = (Px2[0][0] - px[0], Px2[0][1] - px[1]); dy = (Py2[0][0] - py[0], Py2[0][1] - py[1])
                if dx != (0, 0) or dy != (0, 0):
                    shifts[(dx, dy)] += 1; shift_by_pair[(a, b)] += 1
    if i % 100000 == 0 and i: print(f"   ... {i} [{time.time()-t0:.0f}s]", flush=True)
print("Toy 5663b — Kempe shifts of the period datum on T(6,6)")
print(f"  moves changing (P_x,P_y): {sum(shifts.values())}; distinct shift pairs (ΔP_x, ΔP_y): {len(shifts)}")
for s, n in sorted(shifts.items(), key=lambda kv: -kv[1]): print(f"    ΔP_x={s[0]} ΔP_y={s[1]}: {n}")
print(f"  by colour pair: {dict(shift_by_pair)}")
vecs = set()
for (dx, dy) in shifts: 
    if dx != (0, 0): vecs.add(dx)
    if dy != (0, 0): vecs.add(dy)
print(f"  distinct nonzero single-period shift vectors: {sorted(vecs)}")
# lattice generated (2D): compute Hermite-like basis via gcd on integer vectors
import math
def lattice_basis(V):
    V = [list(v) for v in V]
    # Smith/HNF for 2 columns
    from sympy import Matrix
    M = Matrix(V)
    return M.T.columnspace(), Matrix(V).rref()
try:
    from sympy import Matrix, ZZ
    from sympy.matrices.normalforms import hermite_normal_form
    H = hermite_normal_form(Matrix(sorted(vecs)).T) if vecs else None
    print(f"  HNF basis of Λ' (columns): {H.tolist() if H is not None else None}; index in ℤ²: {abs(H.det()) if H is not None and H.shape==(2,2) else 'n/a'}")
except Exception as e: print("  HNF failed:", e)
charges = sorted({v[0] + v[1] for v in vecs}); print(f"  charges x+y of the shift vectors: {charges}  (all ≡ 0 mod 3: {all(c % 3 == 0 for c in charges)})")
# contingency
tab = defaultdict(Counter)
for r in rows: tab[r["cls"]][(tuple(r["Px"]), tuple(r["Py"]), r["deg"])] += 1
for cls, cnt in tab.items():
    print(f"  class {cls}: {sum(cnt.values())} reps, {len(cnt)} distinct (P_x,P_y,deg):")
    for k, n in sorted(cnt.items(), key=lambda kv: -kv[1]): print(f"      P_x={k[0]} P_y={k[1]} deg={k[2]} det/2={(k[0][0]*k[1][1]-k[0][1]*k[1][0])//2}: {n}")
print(f"  [{time.time()-t0:.0f}s]")
